// Des: Copies each object to all store vendors
// Flo: put or delete runs on the main vendor and all mirrors in parallel > a failed mirror is queued per vendor and skipped for the run > drain copies queued objects from any vendor that has them
// I/O: Stor calls (main vendor + mirrors, Db, clock, monthly call budget) > the same Stor calls; only the main vendor's answer decides success; mirror lag never fails a run
// ===================================================================
const std = @import("std"); const stor = @import("sy-clou-stor.zig"); const sqli = @import("st-stor-sqli.zig"); const cfgz = @import("cf-conf-load.zig"); const outb = @import("sy-clou-outb.zig"); const quot = @import("sy-mirr-quot.zig"); const pack = @import("ru-purg-pack.zig"); const fail = @import("ru-fail-over.zig");
pub const CF = .{ .dayz = 86400000, .audt = "mirr_audt", .audc = "mirr_audc", .mput = "mput@", .mdel = "mdel@", .maxt = 8 };
pub const PREF = [_][]const u8{ pack.CF.runs, pack.CF.keep, "cars/", "cont/" };
pub const Memb = struct { name: []const u8, store: stor.Stor, idxz: usize };
pub const Dead = struct { dead: []bool, errz: []anyerror, used: []bool, paus: []bool };
pub fn deadMake(aren: std.mem.Allocator, size: usize) !Dead { const outp: Dead = .{ .dead = try aren.alloc(bool, size), .errz = try aren.alloc(anyerror, size), .used = try aren.alloc(bool, size), .paus = try aren.alloc(bool, size) }; @memset(outp.dead, false); @memset(outp.used, false); @memset(outp.paus, false); @memset(outp.errz, error.Unexpected); return outp; }
pub const Fanz = struct { dbzz: *sqli.Dbzz, iozz: std.Io, nowz: i64, conf: cfgz.Conf, prim: Memb, mirs: []const Memb, stat: *Dead, sent: u32 = 0, qued: u32 = 0 };
pub const Dres = struct { done: u32 = 0, fail: u32 = 0, left: i64 = 0 };
const Kind = enum { put, del2 };
const Jobz = struct { stoz: stor.Stor, iozz: std.Io, keyz: []const u8, byt3: []const u8, kind: Kind, errz: ?anyerror = null, arnz: std.heap.ArenaAllocator };
const Todo = struct { keyz: []const u8, isdl: bool, stat: u8 = 0, errz: anyerror = error.Unexpected };
const Drnz = struct { dest: stor.Stor, srcs: []const stor.Stor, iozz: std.Io, todo: []Todo, arnz: std.heap.ArenaAllocator };
pub fn arenNewz() std.heap.ArenaAllocator { return std.heap.ArenaAllocator.init(std.heap.page_allocator); }
pub fn runzAllz(comptime Typz: type, comptime func: fn (*Typz) void, jobs: []Typz) void { var thrs: [CF.maxt]?std.Thread = @splat(null); for (jobs, 0..) |*jobz, indx| { if (indx == 0) continue; if (indx < thrs.len) { thrs[indx] = std.Thread.spawn(.{}, func, .{jobz}) catch null; if (thrs[indx] == null) func(jobz); } else func(jobz); } if (jobs.len > 0) func(&jobs[0]); for (thrs) |thrd| { if (thrd) |thr2| thr2.join(); } }
fn jobzRunz(jobz: *Jobz) void { const allo = jobz.arnz.allocator(); switch (jobz.kind) { .put => jobz.stoz.put(jobz.stoz.ctx2, allo, jobz.iozz, jobz.keyz, jobz.byt3) catch |err3| { jobz.errz = err3; }, .del2 => jobz.stoz.del2(jobz.stoz.ctx2, allo, jobz.iozz, jobz.keyz) catch |err3| { jobz.errz = err3; } } }
fn kindName(aren: std.mem.Allocator, pref: []const u8, name: []const u8) ![]const u8 { return std.fmt.allocPrint(aren, "{s}{s}", .{ pref, name }); }
pub fn queu(self: *Fanz, aren: std.mem.Allocator, pref: []const u8, name: []const u8, key2: []const u8) !void { try outb.outbAddz(self.dbzz, try kindName(aren, pref, name), key2, self.nowz, true); self.qued += 1; }
fn donz(self: *Fanz, aren: std.mem.Allocator, name: []const u8, key2: []const u8) !void { try outb.outbDone(self.dbzz, try kindName(aren, CF.mput, name), key2); try outb.outbDone(self.dbzz, try kindName(aren, CF.mdel, name), key2); }
fn okay(self: *Fanz, mem: Memb) !bool { if (self.stat.dead[mem.idxz]) return false; if (!try quot.opsaOkay(self.dbzz, mem.name, self.nowz, self.conf.clou_mirr_opsa_mont, 1)) { self.stat.paus[mem.idxz] = true; return false; } return true; }
fn writ(self: *Fanz, aren: std.mem.Allocator, iozz: std.Io, key2: []const u8, byt3: []const u8, kind: Kind) !void { var jobs: std.ArrayList(Jobz) = .empty; var idxz: std.ArrayList(usize) = .empty; const pref = if (kind == .put) CF.mput else CF.mdel; try jobs.append(aren, .{ .stoz = self.prim.store, .iozz = iozz, .keyz = key2, .byt3 = byt3, .kind = kind, .arnz = arenNewz() }); for (self.mirs, 0..) |mem, indx| { if (try okay(self, mem)) { try jobs.append(aren, .{ .stoz = mem.store, .iozz = iozz, .keyz = key2, .byt3 = byt3, .kind = kind, .arnz = arenNewz() }); try idxz.append(aren, indx); } else try queu(self, aren, pref, mem.name, key2); } runzAllz(Jobz, jobzRunz, jobs.items); defer for (jobs.items) |*jobz| jobz.arnz.deinit(); try quot.opsaAddz(self.dbzz, self.prim.name, self.nowz, 1); for (jobs.items[1..], idxz.items) |jobz, indx| { const mem = self.mirs[indx]; try quot.opsaAddz(self.dbzz, mem.name, self.nowz, 1); if (jobz.errz) |err3| { self.stat.dead[mem.idxz] = true; self.stat.errz[mem.idxz] = err3; try queu(self, aren, pref, mem.name, key2); } else { self.stat.used[mem.idxz] = true; self.sent += 1; try donz(self, aren, mem.name, key2); } } if (jobs.items[0].errz) |err3| return err3; }
fn putz(ctx2: *anyopaque, aren: std.mem.Allocator, iozz: std.Io, key2: []const u8, byt3: []const u8) anyerror!void { const self: *Fanz = @ptrCast(@alignCast(ctx2)); return writ(self, aren, iozz, key2, byt3, .put); }
fn delz(ctx2: *anyopaque, aren: std.mem.Allocator, iozz: std.Io, key2: []const u8) anyerror!void { const self: *Fanz = @ptrCast(@alignCast(ctx2)); return writ(self, aren, iozz, key2, "", .del2); }
fn getz(ctx2: *anyopaque, aren: std.mem.Allocator, iozz: std.Io, key2: []const u8) anyerror![]u8 { const self: *Fanz = @ptrCast(@alignCast(ctx2)); var last: anyerror = error.CloudHttp; if (self.prim.store.get(self.prim.store.ctx2, aren, iozz, key2)) |bodz| return bodz else |err3| last = err3; for (self.mirs) |mem| { if (self.stat.dead[mem.idxz]) continue; if (mem.store.get(mem.store.ctx2, aren, iozz, key2)) |bodz| return bodz else |err3| last = err3; } return last; }
fn lisz(ctx2: *anyopaque, aren: std.mem.Allocator, iozz: std.Io, pre2: []const u8) anyerror![]stor.Objz { const self: *Fanz = @ptrCast(@alignCast(ctx2)); try quot.opsaAddz(self.dbzz, self.prim.name, self.nowz, 1); return self.prim.store.list(self.prim.store.ctx2, aren, iozz, pre2); }
pub fn fanzStor(self: *Fanz) stor.Stor { return .{ .ctx2 = self, .put = putz, .get = getz, .del2 = delz, .list = lisz }; }
fn drnzRunz(jobz: *Drnz) void { for (jobz.todo) |*item| { _ = jobz.arnz.reset(.free_all); const allo = jobz.arnz.allocator(); if (item.isdl) { jobz.dest.del2(jobz.dest.ctx2, allo, jobz.iozz, item.keyz) catch |err3| { item.stat = 3; item.errz = err3; return; }; item.stat = 1; continue; } var gotz: ?[]u8 = null; for (jobz.srcs) |srcz| { if (srcz.get(srcz.ctx2, allo, jobz.iozz, item.keyz)) |bodz| { gotz = bodz; break; } else |_| {} } const bodz = gotz orelse { item.stat = 2; continue; }; jobz.dest.put(jobz.dest.ctx2, allo, jobz.iozz, item.keyz, bodz) catch |err3| { item.stat = 3; item.errz = err3; return; }; item.stat = 1; } }
fn packHave(dbzz: *sqli.Dbzz, key2: []const u8) !bool { var stmt = try dbzz.prep("SELECT 1 FROM pack WHERE packk=?1 LIMIT 1;"); defer stmt.fini(); try stmt.bindText(1, key2); return try stmt.step(); }
pub fn lateKeyz(key2: []const u8) bool { return std.mem.startsWith(u8, key2, pack.CF.runs) or std.mem.startsWith(u8, key2, pack.CF.keep); }
pub fn membAllz(self: *Fanz, aren: std.mem.Allocator) ![]Memb { const outp = try aren.alloc(Memb, self.mirs.len + 1); outp[0] = self.prim; for (self.mirs, 0..) |mem, indx| outp[indx + 1] = mem; return outp; }
pub fn fanzLeft(self: *Fanz) !i64 { var stmt = try self.dbzz.prep("SELECT count(*) FROM outb WHERE stat=0 AND (kind LIKE 'mput@%' OR kind LIKE 'mdel@%');"); defer stmt.fini(); _ = try stmt.step(); return stmt.colzIntz(0); }
pub fn fanzDrai(self: *Fanz, aren: std.mem.Allocator) !Dres { var rslt: Dres = .{}; const alls = try membAllz(self, aren); var jobs: std.ArrayList(Drnz) = .empty; var owns: std.ArrayList(usize) = .empty; for (alls, 0..) |mem, indx| { if (self.stat.dead[mem.idxz]) continue; const cntz = try quot.opsaGetz(self.dbzz, mem.name, self.nowz); const room = @as(i64, self.conf.clou_mirr_opsa_mont) - cntz; if (room <= 0) { self.stat.paus[mem.idxz] = true; continue; } const limz = @min(@as(i64, self.conf.clou_mirr_batz), room); const puts = try outb.outbDuez(self.dbzz, aren, try kindName(aren, CF.mput, mem.name), self.nowz, limz); const dels = try outb.outbDuez(self.dbzz, aren, try kindName(aren, CF.mdel, mem.name), self.nowz, @max(limz - @as(i64, @intCast(puts.len)), 0)); if (puts.len + dels.len == 0) continue; const todo = try aren.alloc(Todo, puts.len + dels.len); for (puts, 0..) |item, ind2| todo[ind2] = .{ .keyz = item.keyz, .isdl = false }; for (dels, 0..) |item, ind2| todo[puts.len + ind2] = .{ .keyz = item.keyz, .isdl = true }; var srcs: std.ArrayList(stor.Stor) = .empty; for (alls, 0..) |othr, ind3| { if (ind3 != indx and !self.stat.dead[othr.idxz]) try srcs.append(aren, othr.store); } try jobs.append(aren, .{ .dest = mem.store, .srcs = srcs.items, .iozz = self.iozz, .todo = todo, .arnz = arenNewz() }); try owns.append(aren, indx); } runzAllz(Drnz, drnzRunz, jobs.items); defer for (jobs.items) |*jobz| jobz.arnz.deinit(); for (jobs.items, owns.items) |jobz, indx| { const mem = alls[indx]; var cals: i64 = 0; for (jobz.todo) |item| { const kind = try kindName(aren, if (item.isdl) CF.mdel else CF.mput, mem.name); switch (item.stat) { 1 => { try outb.outbDone(self.dbzz, kind, item.keyz); rslt.done += 1; cals += 1; self.stat.used[mem.idxz] = true; }, 2 => { if (lateKeyz(item.keyz) and !try packHave(self.dbzz, item.keyz)) try outb.outbDone(self.dbzz, kind, item.keyz) else { try outb.outbFail(self.dbzz, kind, item.keyz, "no vendor has this object", self.nowz); rslt.fail += 1; } }, 3 => { try outb.outbFail(self.dbzz, kind, item.keyz, @errorName(item.errz), self.nowz); rslt.fail += 1; cals += 1; self.stat.dead[mem.idxz] = true; self.stat.errz[mem.idxz] = item.errz; }, else => {} } } try quot.opsaAddz(self.dbzz, mem.name, self.nowz, cals); } rslt.left = try fanzLeft(self); return rslt; }
